beforeSaveCustomScript:
// Calculate days remaining until license expiry
if (licenseExpiry != null) {
    daysRemaining = datetime\diff(licenseExpiry, datetime\now(), 'days');
    
    // Set license status based on days remaining
    if (daysRemaining > 30) {
        licenseStatus = 'Active';
    } else if (daysRemaining >= 0 && daysRemaining <= 30) {
        licenseStatus = 'Expiring Soon';
    } else {
        licenseStatus = 'Expired';
    }
} else {
    daysRemaining = null;
    licenseStatus = 'No Expiry';
}
